"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { useAppStore } from "@/lib/store"
import { toast } from "sonner"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
const logSupportAction = (action: string) => {
  console.log(`[AUDIT] Attempted restricted action in Support Mode: ${action}`)
  // In real app, this would send to API
}

const buttonVariants = cva(
  "inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
        outline: "border border-input bg-background hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-4 py-2",
        sm: "h-9 rounded-md px-3",
        lg: "h-11 rounded-md px-8",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
  restrictedInSupportMode?: boolean // Added prop definition
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, restrictedInSupportMode = false, onClick, ...props }, ref) => {
    const isSupportMode = useAppStore((state) => state.isSupportMode)

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (isSupportMode && restrictedInSupportMode) {
        e.preventDefault()
        e.stopPropagation()
        toast.error("Action Restricted", {
          description: "Cannot perform this action in Support Mode",
        })
        logSupportAction(props["aria-label"] || props.children?.toString() || "Unknown Action")
        return
      }
      onClick?.(e)
    }

    const Comp = asChild ? Slot : "button"

    // If restricted and in support mode, wrap in tooltip
    if (isSupportMode && restrictedInSupportMode) {
      return (
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <span className="inline-block cursor-not-allowed">
                <Comp
                  className={cn(buttonVariants({ variant, size, className }), "opacity-50 pointer-events-none")}
                  ref={ref}
                  {...props}
                  onClick={undefined} // Disable click on button itself
                />
              </span>
            </TooltipTrigger>
            <TooltipContent>
              <p>Action restricted in Support Mode</p>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>
      )
    }

    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} onClick={handleClick} {...props} />
    )
  },
)
Button.displayName = "Button"

export { Button, buttonVariants }
